package com.neobank.transaction.repository;
import com.neobank.transaction.domain.Beneficiary; import org.springframework.data.jpa.repository.JpaRepository; import java.time.Instant; import java.util.*;
public interface BeneficiaryRepository extends JpaRepository<Beneficiary,UUID>{List<Beneficiary> findByOwnerUserIdOrderByCreatedAtDesc(UUID owner); Optional<Beneficiary> findByIdAndOwnerUserId(UUID id,UUID owner); boolean existsByOwnerUserIdAndDestinationAccountIdAndAvailableAtLessThanEqual(UUID owner,UUID destination,Instant now);}